       "Modern Age istisnadır: hiç Major Triumph'ı ve Dedication adımı yoktur, çünkü taşınacak bir sonraki Age yoktur. Son Age'de bir Triumph tam olarak anında ödediği kadar eder - artı bir puan Score."
