       "Exploration'da [B]Plague[/B] komşular arasında değil, kıtalar boyunca yayılır; sonraki Crisis Policy'ler Major Outbreak'leri tamamen kesebilir. İmparatorluğun yoğun ve iyi bağlıysa onları erken al."
